const ORIGIN = "https://api.example.com";
const ORIGIN_ALIAS = ORIGIN;
let mutableOrigin = "https://api.example.com/";
mutableOrigin = readOrigin();
declare function readOrigin(): string;

export const hostSuffix = (input: string): Promise<Response> => fetch(`https://api.example.com${input}`);
export const aliasHostSuffix = (input: string): Promise<Response> => fetch(`${ORIGIN_ALIAS}${input}`);
export const concatHostSuffix = (input: string): Promise<Response> => fetch(ORIGIN + input + "/resource");
export const unfinishedPort = (input: string): Promise<Response> => fetch(`https://api.example.com:${input}/resource`);
export const unfinishedUserinfo = (input: string): Promise<Response> => fetch(`https://api.example.com@${input}/resource`);
export const emptyAuthority = (input: string): Promise<Response> => fetch(`https://${input}/resource`);
export const rootSlash = (input: string): Promise<Response> => fetch(`/${input}`);
export const networkPath = (input: string): Promise<Response> => fetch(`//${input}`);
export const backslashAuthority = (input: string): Promise<Response> => fetch(`/\\${input}`);
export const tabAuthority = (input: string): Promise<Response> => fetch(`/\t${input}`);
export const crAuthority = (input: string): Promise<Response> => fetch(`/\r${input}`);
export const lfAuthority = (input: string): Promise<Response> => fetch(`/\n${input}`);
export const changedOrigin = (input: string): Promise<Response> => fetch(`${mutableOrigin}${input}`);
export const shadowedOrigin = (ORIGIN: string, input: string): Promise<Response> => fetch(`${ORIGIN}/path/${input}`);
export const opaqueOrigin = (input: string): Promise<Response> => fetch(`${readOrigin()}/path/${input}`);
export const staticPath = (input: string): Promise<Response> => fetch(`https://api.example.com/path/${input}`);
export const aliasPath = (input: string): Promise<Response> => fetch(`${ORIGIN_ALIAS}/path/${input}`);
export const concatPath = (input: string): Promise<Response> => fetch(ORIGIN + "/path/" + input);
export const nestedConcatPath = (input: string): Promise<Response> => fetch((ORIGIN + "/path/") + input);
export const literalTemplatePath = (input: string): Promise<Response> => fetch(`${"https://api.example.com"}/path/${input}`);
export const nestedTemplatePath = (input: string): Promise<Response> => fetch(`${`${ORIGIN}/path/`}${input}`);
export const relativePath = (input: string): Promise<Response> => fetch(`/path/${input}`);
export const fixedQuery = (input: string): Promise<Response> => fetch(`${ORIGIN}?search=${input}`);
export const fixedFragment = (input: string): Promise<Response> => fetch(`${ORIGIN}#${input}`);
export const cookedPath = (input: string): Promise<Response> => fetch(`https:\x2f\x2fapi.example.com/path/${input}`);
export const completeOrigin = (): Promise<Response> => fetch(ORIGIN + "");
export const pathBackslash = (input: string): Promise<Response> => fetch(`${ORIGIN}/path/\\${input}`);
export const completeRoot = (): Promise<Response> => fetch("/" + "");
